import sys

sys.setrecursionlimit(20000)

class Node:
    def __init__(self, val):
        self.val = val
        self.left = None
        self.right = None

def build_tree(nodes, target):
    if not nodes:
        return None, None

    root = Node(int(nodes[0]))
    queue = [root]
    idx = 1
    found_target = False

    while queue and idx < len(nodes):
        current = queue.pop(0)

        if idx < len(nodes) and nodes[idx] != 'N':
            current.left = Node(int(nodes[idx]))
            if int(nodes[idx]) == target:
                found_target = True
            queue.append(current.left)
        idx += 1

        if idx < len(nodes) and nodes[idx] != 'N': 
            current.right = Node(int(nodes[idx]))
            if int(nodes[idx]) == target and not found_target:
                found_target = True
            queue.append(current.right)
        idx += 1

    return root, found_target

def find_mirror(root, target):
    if not root:
        return -1

    if root.val == target:
        return -1

    stack = [(root, root)]

    while stack:
        left_node, right_node = stack.pop()

        if left_node.val == target:
            if right_node:
                return right_node.val
            else:
                return -1

        if right_node.val == target:
            if left_node:
                return left_node.val
            else:
                return -1

        if left_node and right_node:
            if left_node.left and right_node.right:
                stack.append((left_node.left, right_node.right))
            if left_node.right and right_node.left:
                stack.append((left_node.right, right_node.left))

    return -1

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    n = int(input_data[0])
    target = int(input_data[1])
    nodes = input_data[2:2+n]

    root, _ = build_tree(nodes, target)
    result = find_mirror(root, target)
    print(result)

if __name__ == "__main__":
    main()
